// 定义联合类型：可能为字符串或数字
function processInput(input: string | number): string {
    // 使用 typeof 类型守卫缩窄为 string
    if (typeof input === 'string') {
        // 此处 input 被自动推断为 string
        return input.toUpperCase();
    }
    // 如果前面条件不成立，TypeScript 知道此时 input 一定是 number
    // 这里可以使用 number 特有的方法
    return `Number: ${input.toFixed(2)}`;
}

// 自定义类型谓词：检查值是否为字符串
function isString(value: unknown): value is string {
    return typeof value === 'string';
}

// 使用自定义谓词处理数组
const mixed: unknown[] = ['hello', 42, 'world', true];
const stringsOnly = mixed.filter(isString);  // filter 根据谓词推断类型为 string[]
console.log(stringsOnly);  // ['hello', 'world']

// 可区分联合（Discriminated Union）配合 switch
interface Cat { type: 'cat'; meow: () => void; }
interface Dog { type: 'dog'; bark: () => void; }
type Pet = Cat | Dog;

function handlePet(pet: Pet) {
    switch (pet.type) {
        case 'cat':
            // 此处 pet 自动收窄为 Cat
            pet.meow();
            break;
        case 'dog':
            pet.bark();
            break;
    }
}

